function lesson7Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 7','Đi công viên và kể chuyện một tấm ảnh.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson7Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson7-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson7-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson7References(8,10);bindLesson2Voice(lesson7Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson7Dialogue();};document.querySelectorAll('[data-lesson7-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson7Line.split(',').map(Number);lesson2Speak(lesson7Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson7-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson7Data.dialogues[Number(b.dataset.lesson7Full)][1].map(l=>l[1]).join(' ')));}
function lesson7BTNCMarkup(file){const group=lesson7BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B7; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson7BTNCReference();const id=lesson7BTNC.indexOf(group),saved=state.lesson7Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson7BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l7nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson7BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson7BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson7BTNCReference()+'</details>';}
function lesson7BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 7</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson7/btnc-answers-page18.png" alt="Đáp án BTNC bài 7, trang 18 của PDF"></details>';}
function bindLesson7BTNC(){lesson7BTNC.forEach((group,id)=>{document.querySelector('#lesson7BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l7nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson7BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson7Exercises=state.lesson7Exercises||{};state.lesson7Exercises['btnc'+id]=records;save();document.querySelector('#lesson7BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

