function lesson7References(first=1,last=14){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson7/source-'+(first+i)+'.png" alt="Bài 7 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson7SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson7Home(){app.innerHTML=intro('HSK2 · LESSON 7',lesson7Data.title,lesson7Data.pinyin+' · '+lesson7Data.vi)+'<section class="hero"><div><h2>Kể chi tiết về chuyến đi</h2><p>Hỏi thời gian, địa điểm, phương tiện và người đi cùng; giới thiệu một tấm ảnh.</p><a class="btn" href="#words">Học 21 mục từ →</a></div><div class="hero-mark" aria-hidden="true">骑</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 21</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>77–90</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','是……的 · Hỏi chi tiết sự việc'],['dialogue','Hội thoại','Đi công viên cùng ai · Tấm ảnh ở Pháp'],['practice','Luyện tập','Điền từ · Đọc hiểu · Tranh và ảnh du lịch'],['listening','Luyện nghe','Bốn file Q2B7 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 7']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>上个周末你去哪儿了？<br>你是跟谁一起去的？怎么去的？<br>你今天是怎么来学校的？</p></article>'+lesson7References();}
function lesson7Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 7','Hỏi rõ chi tiết bằng 是……的.','Dùng khi sự việc đã xảy ra và người nói muốn nhấn mạnh một chi tiết cụ thể.')+`<article class="card grammar"><h2>Cấu trúc chính</h2><div class="pattern">Chủ ngữ + 是 + chi tiết cần nhấn mạnh + động từ + 的</div><p>Chi tiết có thể là thời gian, địa điểm, cách thức hoặc người thực hiện. Trong câu khẳng định và câu hỏi, 是 thường có thể lược bỏ.</p></article><article class="card grammar"><h2>01 · Thời gian</h2>${grammarExamples([["你今天是几点来学校的？","Nǐ jīntiān shì jǐ diǎn lái xuéxiào de?","Hôm nay bạn đến trường lúc mấy giờ?"],["我是早上八点十分来学校的。","Wǒ shì zǎoshang bā diǎn shí fēn lái xuéxiào de.","Tôi đến trường lúc 8 giờ 10 sáng."]])}<h2>02 · Địa điểm</h2>${grammarExamples([["这张照片是在哪儿拍的？","Zhè zhāng zhàopiàn shì zài nǎr pāi de?","Bức ảnh này được chụp ở đâu?"],["是在学校拍的。","Shì zài xuéxiào pāi de.","Được chụp ở trường."]])}<h2>03 · Cách thức</h2>${grammarExamples([["你今天是怎么来学校的？","Nǐ jīntiān shì zěnme lái xuéxiào de?","Hôm nay bạn đến trường bằng cách nào?"],["我是走路来学校的。","Wǒ shì zǒulù lái xuéxiào de.","Tôi đi bộ đến trường."]])}<h2>04 · Người thực hiện</h2>${grammarExamples([["这件事是谁告诉你的？","Zhè jiàn shì shì shéi gàosu nǐ de?","Ai đã nói với bạn chuyện này?"],["是朋友告诉我的。","Shì péngyou gàosu wǒ de.","Một người bạn đã nói với tôi."]])}</article><article class="card grammar"><h2>Phủ định và đối chiếu</h2><div class="pattern">Chủ ngữ + 不是 + chi tiết + động từ + 的</div><p>Ở dạng phủ định, không lược 是.</p>${grammarExamples([["我不是一个人来的，是跟我哥哥一起来的。","Wǒ bú shì yí ge rén lái de, shì gēn wǒ gēge yìqǐ lái de.","Tôi không đến một mình, mà đến cùng anh trai."],["不是最近，是去年拍的。","Bú shì zuìjìn, shì qùnián pāi de.","Không phải chụp gần đây, mà chụp năm ngoái."]])}</article><a class="btn" href="#practice">Luyện hỏi chi tiết →</a>`+lesson7References(3,4);}
