function gradeLesson7Exercise(mode,index,draft){const q=lesson7Data.exercises[mode][index],variants=[q[1]];if(mode==='vocab'&&index===0)variants.push('玩');return {correct:variants.some(a=>compareHanzi(draft,a).correct),answer:q[1],note:q[2]};}
function lesson7Practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 7','Bạn đã đi cùng ai, bằng cách nào?','Luyện 是……的 với tranh phương tiện, ảnh và câu hỏi về chuyến đi.')+'<div class="toolbar lesson2-modes">'+[['vocab','Điền từ'],['reading','Đọc hiểu'],['choose','在哪儿 · 怎么 · 什么时候 · 谁'],['pictures','Phương tiện'],['photos','Ảnh du lịch'],['shop','Chuyến đi gần đây'],['summary','Tự tổng kết']].map(([id,title])=>'<button class="btn '+(lesson7PracticeMode===id?'':'secondary')+'" data-lesson7-mode="'+id+'">'+title+'</button>').join('')+'</div><div id="lesson7ExerciseArea"></div>';document.querySelectorAll('[data-lesson7-mode]').forEach(b=>b.onclick=()=>{lesson7PracticeMode=b.dataset.lesson7Mode;lesson7Practice();});renderLesson7ExerciseArea();}
function renderLesson7ExerciseArea(){const area=document.querySelector('#lesson7ExerciseArea'),mode=lesson7PracticeMode;if(mode==='pictures'){renderLesson7Transport(area);return;}if(mode==='photos'){renderLesson7Photos(area);return;}if(mode==='shop'){renderLesson7Shop(area);return;}if(mode==='summary'){area.innerHTML='<article class="card grammar"><h2>Từ ngữ và mẫu câu muốn nhớ</h2><label for="lesson7SummaryWords">Từ ngữ</label><textarea id="lesson7SummaryWords" rows="4"></textarea><label for="lesson7SummaryPatterns">Mẫu câu</label><textarea id="lesson7SummaryPatterns" rows="4"></textarea><p class="sub">Tự động lưu trong tiến độ Lesson 7.</p></article>'+lesson7References(14,14);for(const[id,key]of [['lesson7SummaryWords','words'],['lesson7SummaryPatterns','patterns']]){document.querySelector('#'+id).value=state.lesson7Summary?.[key]||'';document.querySelector('#'+id).oninput=e=>{state.lesson7Summary=state.lesson7Summary||{};state.lesson7Summary[key]=e.target.value;save();};}return;}
 const saved=state.lesson7Exercises?.[mode]||{};
 area.innerHTML=(mode==='reading'?'<article class="card grammar"><h2>Đoạn đọc</h2><p class="lesson2-reading" lang="zh-CN">'+lesson7Data.reading+'</p><p class="sub">Từ hỗ trợ: 海南 (Hải Nam), 飞机 (máy bay), 海边 (bờ biển), 两个半小时 (hai tiếng rưỡi).</p></article>':'')+'<form id="lesson7ExerciseForm">'+lesson7Data.exercises[mode].map((q,i)=>'<article class="card grammar"><label for="lesson7Answer'+i+'">'+(i+1)+'. '+esc(q[0])+'</label><input class="lesson2-answer" id="lesson7Answer'+i+'" lang="zh-CN" placeholder="Gõ chữ Hán…" value="'+esc(saved[i]?.draft||'')+'"><div id="lesson7Feedback'+i+'" role="status"></div></article>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson7Result" role="status"></p></form>'+(mode==='reading'?'<h2>Chọn đáp án theo đoạn văn</h2><form id="lesson7ReadingQuiz">'+lesson7Data.exercises.comprehension.map((q,i)=>'<fieldset class="card question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l7reading'+i+'" value="'+j+'"> '+v+'</label>').join('')+'<div id="lesson7ReadingFeedback'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra đọc hiểu</button><p id="lesson7ReadingResult" role="status"></p></form>':'')+lesson7References(mode==='vocab'?2:13,mode==='vocab'?3:14);
 document.querySelector('#lesson7ExerciseForm').onsubmit=e=>{e.preventDefault();const records={};let count=0;lesson7Data.exercises[mode].forEach((q,i)=>{const draft=document.querySelector('#lesson7Answer'+i).value,r=gradeLesson7Exercise(mode,i,draft);records[i]={draft,correct:r.correct};count+=r.correct?1:0;document.querySelector('#lesson7Feedback'+i).innerHTML='<div class="feedback '+(r.correct?'good':'bad')+'">'+(r.correct?'✓ Chính xác':'Đáp án tham khảo: '+esc(r.answer))+'<br>'+esc(r.note)+'</div>';});state.lesson7Exercises=state.lesson7Exercises||{};state.lesson7Exercises[mode]=records;save();document.querySelector('#lesson7Result').textContent='Đúng '+count+' / '+lesson7Data.exercises[mode].length+' câu.';};
 if(mode==='reading')document.querySelector('#lesson7ReadingQuiz').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;lesson7Data.exercises.comprehension.forEach((q,i)=>{const answer=form.get('l7reading'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson7ReadingFeedback'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson7Exercises=state.lesson7Exercises||{};state.lesson7Exercises.comprehension=records;save();document.querySelector('#lesson7ReadingResult').textContent='Đúng '+count+' / 4 câu.';};
}

function lesson7Listening(){const groups=[{"title":"07-1 · Đi công viên cùng ai?","d":0,"tf":[["卡玛拉周末去公园了。","Đúng."],["她是一个人去的。","Sai — đi cùng bạn Trung Quốc."],["她觉得一个人去公园很有意思。","Sai — cô ấy nói 一个人去公园没意思."],["她是骑自行车去的。","Đúng."]],"questions":[["卡玛拉是跟谁一起去公园的？","跟中国朋友一起去的。"],["他们是怎么去的？","骑自行车去的。"],["他们骑了多长时间？","一个小时左右。"],["他们觉得累不累？","不累。"]]},{"title":"07-2 · Tấm ảnh chụp ở Pháp","d":1,"questions":[["海伦觉得那张照片怎么样？","很漂亮。"],["那张照片是谁拍的？","海伦的男朋友拍的。"],["那张照片是什么时候拍的？","去年。"],["那张照片是在哪儿拍的？","在法国。"]]}];app.innerHTML=intro('LUYỆN NGHE · BÀI 7','Nghe và luyện theo tình huống.','Bốn file Q2B7 bạn cung cấp, kèm bản ghi BTNC và câu tự luyện.')+'<div class="notice">File Q2B7 thuộc bộ BTNC. Phần bản ghi và đáp án NC1–NC3 được đối chiếu theo PDF bài 7. Chưa xác định bản thu tương ứng mã 07-1, 07-2, 07-3 trong giáo trình.</div>'+['Q2B7.mp3','Q2B7.NC1.MP3','Q2B7.NC2.MP3','Q2B7.NC3.MP3'].map((file,i)=>'<article class="card grammar"><h3>'+file+'</h3><audio controls preload="none" src="audio/'+file+'"></audio><label>Tốc độ <select data-lesson7-audio="'+i+'" aria-label="Tốc độ '+file+'"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label>'+lesson7BTNCMarkup(file)+'</article>').join('')+'<h2>Luyện thêm theo văn bản giáo trình</h2>'+lesson2VoiceControls()+groups.map(g=>'<article class="card grammar"><h2>'+g.title+'</h2><button class="btn secondary" data-lesson7-listen="'+g.d+'">▶ Nghe toàn hội thoại bằng giọng thiết bị</button>'+(g.tf?'<h3>Nhận định đúng / sai</h3>'+g.tf.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join(''):'')+'<h3>Nghe và trả lời</h3>'+g.questions.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p class="sub">Đối chiếu theo văn bản hội thoại, không phải đáp án từ audio BTNC.</p></article>').join('')+'<article class="card grammar"><h2>07-3 · Bài nghe mở rộng trong giáo trình</h2><p class="notice">Chưa có bản ghi lời nghe xác nhận cho mã 07-3 nên chưa chấm điểm phần này.</p><h3>Đúng / sai</h3><ol><li>美京的衬衫很好看。</li><li>衬衫是美京自己买的。</li><li>美京自己不太喜欢这件衬衫。</li><li>美京的衣服都很漂亮。</li></ol><h3>Chọn đáp án</h3><ol><li>这件衬衫是谁买的？<br>A. 美京　B. 美京的妈妈　C. 美京和妈妈</li><li>这件衬衫是什么时候买的？<br>A. 最近　B. 今年　C. 去年</li><li>这件衬衫是在哪儿买的？<br>A. 中国　B. 美国　C. 韩国</li><li>为什么海伦想跟美京一起去买衣服？<br>A. 美京可以帮她　B. 海伦喜欢美京　C. 美京的衣服很多</li></ol></article>'+lesson7References(12,14);bindLesson7BTNC();document.querySelectorAll('[data-lesson7-audio]').forEach(select=>select.onchange=()=>{document.querySelectorAll('audio')[Number(select.dataset.lesson7Audio)].playbackRate=Number(select.value);});document.querySelectorAll('audio').forEach(audio=>audio.onplay=()=>{stopWordAudio();document.querySelectorAll('audio').forEach(other=>{if(other!==audio)other.pause();});});bindLesson2Voice(lesson7Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelectorAll('[data-lesson7-listen]').forEach(b=>b.onclick=()=>lesson2Speak(lesson7Data.dialogues[Number(b.dataset.lesson7Listen)][1].map(l=>l[1]).join(' ')));}
function renderLesson7Shop(area){const p=state.lesson7Trip||{};area.innerHTML='<article class="card grammar"><h2>Giới thiệu chuyến đi gần đây</h2><p class="sub">Điền các cụm từ để luyện hỏi đáp nhấn mạnh từng chi tiết.</p>'+[['place','Bạn đã đi đâu?','海南'],['time','Đi khi nào?','去年'],['manner','Đi bằng cách nào?','坐飞机'],['companion','Đi cùng ai?','男朋友'],['feeling','Cảm nhận','很有意思']].map(([key,label,hint])=>'<label for="lesson7Trip'+key+'">'+label+'</label><input class="lesson2-answer" id="lesson7Trip'+key+'" data-lesson7-trip="'+key+'" value="'+esc(p[key]||'')+'" placeholder="'+hint+'">').join('')+'<button class="btn" id="lesson7TripMake">Tạo hội thoại tham khảo</button><p id="lesson7TripOutput" style="white-space:pre-line;line-height:2"></p></article>'+lesson7References(11,11);document.querySelectorAll('[data-lesson7-trip]').forEach(input=>input.oninput=e=>{state.lesson7Trip=state.lesson7Trip||{};state.lesson7Trip[input.dataset.lesson7Trip]=e.target.value;save();});document.querySelector('#lesson7TripMake').onclick=()=>{const p=state.lesson7Trip||{};document.querySelector('#lesson7TripOutput').textContent='A：你最近去哪儿旅行了？\nB：我去'+(p.place||'海南')+'旅行了。\nA：你是什么时候去的？\nB：我是'+(p.time||'去年')+'去的。\nA：你是怎么去的？\nB：我是'+(p.manner||'坐飞机')+'去的。\nA：你是跟谁一起去的？\nB：我是跟'+(p.companion||'男朋友')+'一起去的。\nA：你觉得怎么样？\nB：我觉得'+(p.feeling||'很有意思')+'。';};}
for(const[route,handler]of Object.entries({home:lesson7Home,grammar:lesson7Grammar,dialogue:lesson7Dialogue,practice:lesson7Practice,listening:lesson7Listening}))pages[route]=function(){if(state.lesson==='7')handler();else lesson7PreviousPages[route]();};
pages.writing=function(){lesson7PreviousPages.writing();if(state.lesson!=='7')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 7';const chars=[...new Set(lesson7Data.rows.map(r=>r[0]).join('').split('').filter(c=>/[\u3400-\u9fff]/.test(c)))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
render();
const lesson7TransportScenes=[{place:'博物馆',manner:'坐出租车',companion:'哥哥'},{place:'图书馆',manner:'坐公共汽车',companion:'朋友'},{place:'公园',manner:'坐地铁',companion:'爸爸妈妈'},{place:'电影院',manner:'走路',companion:'一个人'}];
function lesson7TransportAnswers(scene){return ['我去'+scene.place+'了','我是'+scene.manner+'去的',scene.companion==='一个人'?'我是一个人去的':'我是跟'+scene.companion+'一起去的'];}
function lesson7AnswerMatches(draft,expected){return [expected,expected.replace(/^我是/,'我'),expected.replace(/^是/,'')].some(text=>compareHanzi(draft,text).correct);}
function renderLesson7Transport(area){const saved=state.lesson7Exercises?.transport||{};area.innerHTML='<p class="sub">按以下组合练习 · Theo bốn tổ hợp luyện tập dưới đây. Các địa điểm, phương tiện và người đi cùng lấy từ trang 81–82; sách cho phép tự chọn cách kết hợp.</p><div class="grid">'+lesson7TransportScenes.map((scene,i)=>'<article class="card grammar"><h3>'+scene.place+' · '+scene.manner+' · '+scene.companion+'</h3>'+['你周末去哪儿了？','你是怎么去的？','你是跟谁一起去的？'].map((q,j)=>'<label for="lesson7Transport'+i+'-'+j+'">'+q+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson7Transport'+i+'-'+j+'" value="'+esc(saved[i]?.drafts?.[j]||'')+'"><p id="lesson7TransportFeedback'+i+'-'+j+'" role="status"></p>').join('')+'<button class="btn secondary" data-lesson7-transport="'+i+'">Kiểm tra</button></article>').join('')+'</div>'+lesson7References(5,6);document.querySelectorAll('[data-lesson7-transport]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson7Transport),expected=lesson7TransportAnswers(lesson7TransportScenes[i]),drafts=[],results=[];expected.forEach((answer,j)=>{const draft=document.querySelector('#lesson7Transport'+i+'-'+j).value,correct=lesson7AnswerMatches(draft,answer);drafts.push(draft);results.push(correct);document.querySelector('#lesson7TransportFeedback'+i+'-'+j).textContent=correct?'✓ Chính xác':'Mẫu tham khảo: '+answer+'。';});state.lesson7Exercises=state.lesson7Exercises||{};state.lesson7Exercises.transport=state.lesson7Exercises.transport||{};state.lesson7Exercises.transport[i]={drafts,results};save();});}
const lesson7PhotoScenes=[{who:'大卫',time:'去年',place:'美国'},{who:'高小明',time:'上个周末',place:'上海'}];
function lesson7PhotoAnswers(scene){return ['是'+scene.who+'拍的','是'+scene.time+'拍的','是在'+scene.place+'拍的'];}
function renderLesson7Photos(area){const saved=state.lesson7Exercises?.photos||{};area.innerHTML='<article class="card grammar"><h2>这张照片是谁拍的？</h2><p class="sub">Theo hai ảnh và từ gợi ý ở trang 83.</p><img loading="lazy" src="images/lesson7/source-7.png" alt="Hai ảnh du lịch của David ở Mỹ và Cao Tiểu Minh ở Thượng Hải" style="display:block;max-width:100%;width:480px;margin:12px auto">'+lesson7PhotoScenes.map((scene,i)=>'<h3>'+(i+1)+'. '+scene.who+' · '+scene.time+' · '+scene.place+'</h3>'+['这张照片是谁拍的？','是什么时候拍的？','是在哪儿拍的？'].map((q,j)=>'<label for="lesson7Photo'+i+'-'+j+'">'+q+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson7Photo'+i+'-'+j+'" value="'+esc(saved[i]?.drafts?.[j]||'')+'"><p id="lesson7PhotoFeedback'+i+'-'+j+'" role="status"></p>').join('')+'<button class="btn secondary" data-lesson7-photo="'+i+'">Kiểm tra</button>').join('')+'</article>';document.querySelectorAll('[data-lesson7-photo]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson7Photo),answers=lesson7PhotoAnswers(lesson7PhotoScenes[i]),drafts=[],results=[];answers.forEach((answer,j)=>{const draft=document.querySelector('#lesson7Photo'+i+'-'+j).value,correct=lesson7AnswerMatches(draft,answer);drafts.push(draft);results.push(correct);document.querySelector('#lesson7PhotoFeedback'+i+'-'+j).textContent=correct?'✓ Chính xác':'Mẫu tham khảo: '+answer+'。';});state.lesson7Exercises=state.lesson7Exercises||{};state.lesson7Exercises.photos=state.lesson7Exercises.photos||{};state.lesson7Exercises.photos[i]={drafts,results};save();});}
